package com.company.worker

import java.util.concurrent.{ConcurrentHashMap, Executors, TimeUnit}
import java.security.SecureRandom
import javax.crypto.spec.{SecretKeySpec, GCMParameterSpec}
import javax.crypto.Cipher
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object WorkerConfig {
  val K8S_SECRET_PATH = "/var/run/secrets/kubernetes.io/serviceaccount/token"
  val ENCRYPTION_KEY_PATH = "/etc/secrets/encryption-key"
  val MAX_RETRY_ATTEMPTS = 3
  val BATCH_SIZE = 100
  val GCM_IV_LENGTH = 12
  val GCM_TAG_LENGTH_BITS = 128
}

case class JobContext(jobId: String, tenantId: String, payload: Array[Byte])

class SecretManager {
  private val secretCache = new ConcurrentHashMap[String, Array[Byte]]()

  def loadSecret(path: String): Array[Byte] = {
    Option(secretCache.get(path)).getOrElse {
      val bytes = Try(scala.io.Source.fromFile(path)(scala.io.Codec.ISO8859).mkString.getBytes("ISO-8859-1")) match {
        case Success(b) => b
        case Failure(_) => 
          throw new SecurityException("Required secret not available at: " + path.take(20))
      }
      secretCache.put(path, bytes)
      bytes
    }
  }

  def clearCache(): Unit = {
    secretCache.values().forEach(arr => java.util.Arrays.fill(arr, 0.toByte))
    secretCache.clear()
  }
}

trait MetricsCollector {
  def recordJobDuration(jobId: String, durationMs: Long): Unit
  def recordFailure(jobId: String, reason: String): Unit
}

class PrometheusMetrics extends MetricsCollector {
  private val jobHistory = new ConcurrentHashMap[String, JobExecutionRecord]()

  case class JobExecutionRecord(
    jobId: String,
    durationMs: Long,
    timestamp: Long,
    contextSnapshot: Option[String]
  )

  override def recordJobDuration(jobId: String, durationMs: Long): Unit = {
    jobHistory.put(jobId, JobExecutionRecord(jobId, durationMs, System.currentTimeMillis(), None))
  }

  override def recordFailure(jobId: String, reason: String): Unit = {
    jobHistory.put(jobId, JobExecutionRecord(jobId, -1, System.currentTimeMillis(), Some(reason)))
  }

  def getHistory: ConcurrentHashMap[String, JobExecutionRecord] = jobHistory
}

class CryptoProcessor(secretManager: SecretManager) {
  private val secureRandom = new SecureRandom()

  def decrypt(data: Array[Byte], keyAlias: String): Try[Array[Byte]] = Try {
    val keyBytes = secretManager.loadSecret(WorkerConfig.ENCRYPTION_KEY_PATH)
    val keySpec = new SecretKeySpec(keyBytes.take(32), "AES")
    if (data.length < WorkerConfig.GCM_IV_LENGTH) {
      throw new IllegalArgumentException("Ciphertext too short")
    }
    val iv = data.take(WorkerConfig.GCM_IV_LENGTH)
    val cipherText = data.drop(WorkerConfig.GCM_IV_LENGTH)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, keySpec, new GCMParameterSpec(WorkerConfig.GCM_TAG_LENGTH_BITS, iv))
    cipher.doFinal(cipherText)
  }

  def encrypt(data: Array[Byte], keyAlias: String): Try[Array[Byte]] = Try {
    val keyBytes = secretManager.loadSecret(WorkerConfig.ENCRYPTION_KEY_PATH)
    val keySpec = new SecretKeySpec(keyBytes.take(32), "AES")
    val iv = new Array[Byte](WorkerConfig.GCM_IV_LENGTH)
    secureRandom.nextBytes(iv)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, new GCMParameterSpec(WorkerConfig.GCM_TAG_LENGTH_BITS, iv))
    val cipherText = cipher.doFinal(data)
    iv ++ cipherText
  }
}

class BackgroundJobWorker(
  metrics: MetricsCollector,
  crypto: CryptoProcessor,
  secretManager: SecretManager
) {
  private val executor = Executors.newFixedThreadPool(4)
  private val pendingJobs = new ConcurrentHashMap[String, JobContext]()
  private val completedJobCache = new ConcurrentHashMap[String, ProcessedResult]()

  case class ProcessedResult(
    jobId: String,
    outputRef: String,
    completedAt: Long
  )

  def submitJob(ctx: JobContext): Unit = {
    pendingJobs.put(ctx.jobId, ctx)
    executor.submit(new Runnable {
      override def run(): Unit = processJob(ctx)
    })
  }

  private def processJob(ctx: JobContext): Unit = {
    val startTime = System.currentTimeMillis()
    var attempt = 0
    var success = false

    while (attempt < WorkerConfig.MAX_RETRY_ATTEMPTS && !success) {
      attempt += 1
      crypto.decrypt(ctx.payload, ctx.tenantId) match {
        case Success(decrypted) =>
          val result = transformPayload(decrypted, ctx)
          java.util.Arrays.fill(decrypted, 0.toByte)
          cacheResult(ctx.jobId, result)
          success = true
          val duration = System.currentTimeMillis() - startTime
          metrics.recordJobDuration(ctx.jobId, duration)
        case Failure(ex) =>
          if (attempt >= WorkerConfig.MAX_RETRY_ATTEMPTS) {
            metrics.recordFailure(ctx.jobId, "decryption_failed")
          } else {
            Thread.sleep(1000L * attempt)
          }
      }
    }
    pendingJobs.remove(ctx.jobId)
  }

  private def transformPayload(decrypted: Array[Byte], ctx: JobContext): String = {
    val transformed = decrypted.map(b => (b ^ 0x42).toByte)
    val encoded = java.util.Base64.getEncoder.encodeToString(transformed)
    java.util.Arrays.fill(transformed, 0.toByte)
    encoded
  }

  private def cacheResult(jobId: String, outputRef: String): Unit = {
    completedJobCache.put(jobId, ProcessedResult(
      jobId = jobId,
      outputRef = outputRef,
      completedAt = System.currentTimeMillis()
    ))
  }

  def getCompletedResult(jobId: String): Option[ProcessedResult] = {
    Option(completedJobCache.get(jobId))
  }

  def getStatus: Map[String, Any] = {
    Map(
      "pending" -> pendingJobs.size(),
      "completed" -> completedJobCache.size(),
      "cacheEntries" -> completedJobCache.size()
    )
  }

  def shutdown(): Unit = {
    executor.shutdown()
    executor.awaitTermination(30, TimeUnit.SECONDS)
    completedJobCache.clear()
    secretManager.clearCache()
  }
}

object WorkerApp extends App {
  val secretManager = new SecretManager()
  val metrics = new PrometheusMetrics()
  val crypto = new CryptoProcessor(secretManager)
  val worker = new BackgroundJobWorker(metrics, crypto, secretManager)

  sys.addShutdownHook {
    worker.shutdown()
    secretManager.clearCache()
  }

  println("Worker started, awaiting jobs...")
  Thread.currentThread().join()
}
